+    /// not -2). Keyed by coefficient position `0..32`.
+    fn step_bias(i: usize) -> (i32, i32) {
+        match i {
+            0 => (16, 8),
+            1 | 2 => (16, 2),
+            3 => (48, 32),
+            4..=11 => (4, 0),
+            12 => (8, 2),
+            13..=15 => (8, 0),
+            _ => (2, 0), // 16..=31
