+    /// Number of escape bits a signed value `v` occupies: `0 -> 1`; else `unary(c) ++ [term if
+    /// c<cmax] ++ offset(c-1) ++ sign`.
+    fn esc_len(v: i32, cmax: u32) -> usize {
+        if v == 0 {
+            return 1;
+        }
+        let c = mag_category(v);
+        c as usize + usize::from(c < cmax) + (c as usize - 1) + 1
+    }
