+    /// Max AC magnitude category (the maximum category omits the unary 0-terminator).
+    const AC_CMAX: u32 = 9;
+
+    /// LSB-first bit accumulator for the AC-strip coder (no final padding, unlike [`Vlc`]).
+    struct Bits {
+        out: KVec<u8>,
+        n: usize,
+    }
+
+    impl Bits {
